/* SVM3D tutorial: send two synthetic NV12 camera frames and save ABGR output. */
#include <linux/dma-buf.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "media_api.h"
#include "media_svm_3d.h"
#define W 640
#define H 480
#define POOL_A 27
#define POOL_B 28
#define POOL_OUT 29
static int frame(int pool,const MEDIA_VIDEO_LAYOUT *l,size_t n,int k,MEDIA_BUFFER *b){MEDIA_BUFFER_META m;unsigned char*p;if(MEDIA_POOL_GetBuffer(pool,b))return -1;p=MEDIA_POOL_GetVaddr(*b);if(!p||MEDIA_POOL_BeginCpuAccess(*b,DMA_BUF_SYNC_WRITE))goto bad;memset(p,0,n);for(int y=0;y<H;y++)for(int x=0;x<W;x++)p[(size_t)y*l->pitch_bytes[0]+x]=(unsigned char)(k?50+y*180/H:50+x*180/W);for(int y=0;y<H/2;y++)for(int x=0;x<W;x+=2){unsigned char*q=p+l->offset_bytes[1]+(size_t)y*l->pitch_bytes[1]+x;q[0]=90;q[1]=180;}MEDIA_POOL_EndCpuAccess(*b,DMA_BUF_SYNC_WRITE);memset(&m,0,sizeof(m));m.valid=1;m.type=MEDIA_BUFFER_META_VIDEO_FRAME;m.media_format=MEDIA_FORMAT_NV12;m.len=n;m.u.video=*l;m.time_stamp=1000000;m.seq=1;if(MEDIA_BUFFER_SetMeta(*b,&m)==0)return 0;bad:MEDIA_POOL_PutBuffer(*b);return -1;}
int main(int argc,char**argv){const char*outp=argc>1?argv[1]:"svm_3d_frame.rgba";const char*plugin=argc>2?argv[2]:"../../plugins/libmedia_svm_3d.so"; const char*asset=argc>3?argv[3]:NULL;int r=1,created=0,started=0;MEDIA_VIDEO_LAYOUT in,outl;size_t ni=0,no=0;MEDIA_BUFFER a,b,o;MEDIA_BUFFER_META m;FILE*f;if(MEDIA_SYS_Init()!=0||MEDIA_PLUGIN_Load(plugin)<0)goto done;if(MEDIA_VIDEO_BuildLinearLayout(W,H,MEDIA_FORMAT_NV12,&in,&ni)!=0||MEDIA_VIDEO_BuildLinearLayout(1280,720,MEDIA_FORMAT_ABGR8888,&outl,&no)!=0)goto done;if(MEDIA_POOL_CreateWithMode(POOL_A,ni,4,MEDIA_POOL_ALLOC_MODE_NATIVE)||MEDIA_POOL_CreateWithMode(POOL_B,ni,4,MEDIA_POOL_ALLOC_MODE_NATIVE)||MEDIA_POOL_CreateWithMode(POOL_OUT,no,4,MEDIA_POOL_ALLOC_MODE_NATIVE))goto done;MEDIA_SVM3D_ATTR x;memset(&x,0,sizeof(x));x.asset_path=asset; x.input_count=2;x.input_format=MEDIA_FORMAT_NV12;x.in_width=W;x.in_height=H;x.in_stride=in.pitch_bytes[0];x.output_format=MEDIA_FORMAT_ABGR8888;x.out_width=1280;x.out_height=720;x.out_stride=outl.pitch_bytes[0];x.output_pool_id=POOL_OUT;x.input_depth=4;x.sync_timeout_ms=100;x.sync_wait_inputs=1;r=MEDIA_PLUGIN_CreateModule("SVM3D",0,&x,sizeof(x));if(r)goto done;created=1;r=MEDIA_PLUGIN_Start("SVM3D",0);if(r)goto done;started=1;if(frame(POOL_A,&in,ni,0,&a)||frame(POOL_B,&in,ni,1,&b))goto done;if(MEDIA_SVM3D_SendFrame(0,0,a,1000)||MEDIA_SVM3D_SendFrame(0,1,b,1000))goto done;r=MEDIA_SVM3D_GetFrame(0,&o,5000);if(r)goto done;if(MEDIA_BUFFER_GetMeta(o,&m)!=0||MEDIA_POOL_BeginCpuAccess(o,DMA_BUF_SYNC_READ)!=0){MEDIA_SVM3D_ReleaseFrame(0,o);goto done;}f=fopen(outp,"wb");void*p=MEDIA_POOL_GetVaddr(o);size_t n=m.len<MEDIA_POOL_GetSize(o)?m.len:MEDIA_POOL_GetSize(o);r=(f&&p&&fwrite(p,1,n,f)==n)?0:1;if(f)fclose(f);MEDIA_POOL_EndCpuAccess(o,DMA_BUF_SYNC_READ);MEDIA_SVM3D_ReleaseFrame(0,o);if(!r)printf("SVM3D %ux%u ABGR bytes=%zu -> %s\n",m.u.video.visible_width,m.u.video.visible_height,n,outp);done:if(started)MEDIA_PLUGIN_Stop("SVM3D",0);if(created)MEDIA_PLUGIN_DestroyModule("SVM3D",0);MEDIA_POOL_Destroy(POOL_OUT);MEDIA_POOL_Destroy(POOL_B);MEDIA_POOL_Destroy(POOL_A);MEDIA_SYS_Exit();return r?1:0;}
